function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'FoodRatings' || !Array.isArray(args[0]) || args[0].length !== 3) return 'Start with FoodRatings(foods, cuisines, ratings).';
  const [foods, cuisines, ratings] = args[0];
  if (![foods, cuisines, ratings].every(Array.isArray)) return 'foods, cuisines and ratings are arrays.';
  const n = foods.length;
  if (n < 1 || n > 20000) return 'There are 1 to 2 * 10^4 foods.';
  if (cuisines.length !== n || ratings.length !== n) return 'foods, cuisines and ratings need the same length.';
  const name = (s) => typeof s === 'string' && /^[a-z]{1,10}$/.test(s);
  const rated = (r) => Number.isInteger(r) && r >= 1 && r <= 100000000;
  if (!foods.every(name) || !cuisines.every(name)) return 'Names are 1 to 10 lowercase letters.';
  if (!ratings.every(rated)) return 'Ratings are whole numbers from 1 to 10^8.';
  const menu = new Set(foods);
  if (menu.size !== n) return 'Food names must be distinct.';
  const kinds = new Set(cuisines);
  if (operations.length - 1 > 20000) return 'At most 2 * 10^4 calls.';
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'changeRating') {
      if (a.length !== 2 || !menu.has(a[0])) return 'changeRating needs a food on the menu.';
      if (!rated(a[1])) return 'newRating is a whole number from 1 to 10^8.';
    } else if (operations[i] === 'highestRated') {
      if (a.length !== 1 || !kinds.has(a[0])) return 'highestRated needs a cuisine that has a food.';
    } else {
      return 'Only changeRating and highestRated can follow the constructor.';
    }
  }
  return null;
}

