class FoodRatings {
  constructor(foods, cuisines, ratings) {
    this.rating = new Map();
    this.cuisineOf = new Map();
    this.heaps = new Map();
    for (let i = 0; i < foods.length; i++) {
      this.rating.set(foods[i], ratings[i]);
      this.cuisineOf.set(foods[i], cuisines[i]);
      if (!this.heaps.has(cuisines[i])) {
        this.heaps.set(cuisines[i], []);
      }
      this.push(this.heaps.get(cuisines[i]), [ratings[i], foods[i]]);
    }
  }

  changeRating(food, newRating) {
    this.rating.set(food, newRating);
    this.push(this.heaps.get(this.cuisineOf.get(food)), [newRating, food]);
  }

  highestRated(cuisine) {
    const heap = this.heaps.get(cuisine);
    while (this.rating.get(heap[0][1]) !== heap[0][0]) {
      this.pop(heap);
    }
    return heap[0][1];
  }

  before(a, b) {
    return a[0] > b[0] || (a[0] === b[0] && a[1] < b[1]);
  }

  push(heap, entry) {
    heap.push(entry);
    let index = heap.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (!this.before(heap[index], heap[parent])) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  }

  pop(heap) {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let index = 0;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let best = index;
      if (left < heap.length && this.before(heap[left], heap[best])) best = left;
      if (right < heap.length && this.before(heap[right], heap[best])) best = right;
      if (best === index) return;
      [heap[best], heap[index]] = [heap[index], heap[best]];
      index = best;
    }
  }
}

