class FoodRatings {
  constructor(foods, cuisines, ratings) {
    this.items = foods.map((food, i) => ({ food, cuisine: cuisines[i], rating: ratings[i] }));
  }
  changeRating(food, newRating) {
    this.items.find(item => item.food === food).rating = newRating;
  }
  highestRated(cuisine) {
    // Sort the cuisine's foods by rating (high first), then by name, and take the first.
    const list = this.items.filter(item => item.cuisine === cuisine);
    list.sort((a, b) => b.rating - a.rating || (a.food < b.food ? -1 : 1));
    return list[0].food;
  }
}

