function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  // Small alphabets and short names give many shared prefixes and ties on the name order.
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz'.slice(0, int(3, 26)) : ['ab', 'abc', 'xyz'][int(0, 2)];
  const word = (maxLength) => Array.from({ length: int(1, maxLength) }, () => letters[int(0, letters.length - 1)]).join('');
  const n = large ? int(1200, 1500) : int(1, 6);
  const names = new Set();
  for (let tries = 0; names.size < n && tries < 100000; tries++) names.add(word(large ? 10 : 3));
  const foods = [...names];
  const kinds = Array.from(new Set(Array.from({ length: large ? int(1, 30) : int(1, 3) }, () => word(large ? 10 : 2))));
  const cuisines = foods.map(() => kinds[int(0, kinds.length - 1)]);
  const top = large ? [5, 1000, 100000000][int(0, 2)] : (rand() < 0.8 ? 4 : 100000000);
  const ratings = foods.map(() => int(1, top));
  const operations = ['FoodRatings'];
  const args = [[foods, cuisines, ratings]];
  const calls = large ? 499 : int(1, 12);
  for (let i = 0; i < calls; i++) {
    if (rand() < 0.5) {
      operations.push('changeRating');
      args.push([foods[int(0, foods.length - 1)], int(1, top)]);
    } else {
      operations.push('highestRated');
      args.push([cuisines[int(0, cuisines.length - 1)]]);
    }
  }
  return [operations, args];
}
